package com.ptms.domain;import jakarta.persistence.*;import java.time.*;@Entity @Table(name="app_user") public class AppUser{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="full_name") private String fullName;@Column(unique=true) private String username;@Column(unique=true) private String email;@Column(name="password_hash") private String passwordHash;@Enumerated(EnumType.STRING) private UserRole role;private boolean enabled=true;@Column(name="must_change_password") private boolean mustChangePassword;@Column(name="reset_token") private String resetToken;@Column(name="reset_token_expires_at") private LocalDateTime resetTokenExpiresAt;@Column(name="profile_image",columnDefinition="LONGTEXT") private String profileImage;@Column(name="created_at") private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public String getFullName(){return fullName;}public void setFullName(String v){fullName=v;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String v){passwordHash=v;}public UserRole getRole(){return role;}public void setRole(UserRole v){role=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public boolean isMustChangePassword(){return mustChangePassword;}public void setMustChangePassword(boolean v){mustChangePassword=v;}public String getResetToken(){return resetToken;}public void setResetToken(String v){resetToken=v;}public LocalDateTime getResetTokenExpiresAt(){return resetTokenExpiresAt;}public void setResetTokenExpiresAt(LocalDateTime v){resetTokenExpiresAt=v;}public String getProfileImage(){return profileImage;}public void setProfileImage(String v){profileImage=v;}}
